var rows = JSON.parse(value), newest = null, groups = {}, result = [], i, m, url, host, parts, path, key;
if (!Array.isArray(rows)) {
	throw 'Unexpected result: ' + value.substring(0, 200);
}
for (i = 0; i < rows.length; i++) {
	if (newest === null || Number(rows[i].clock) > newest) {
		newest = Number(rows[i].clock);
	}
}
for (i = 0; i < rows.length; i++) {
	url = rows[i]['SpanAttributes.url.full'] || rows[i]['SpanAttributes.http.url'] || '';
	if (url === '' || Number(rows[i].clock) !== newest || isNaN(Number(rows[i].count))) {
		continue;
	}
	m = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#]*)([^?#]*)/i.exec(url);
	host = m ? m[1] : '';
	parts = (m ? m[2] : url.split(/[?#]/)[0]).split('/');
	path = '';
	for (var j = 0; j < parts.length; j++) {
		if (parts[j] === '') {
			continue;
		}
		path += '/' + (/^[0-9]+$/.test(parts[j])
			|| (parts[j].length >= 6 && /^[A-Za-z0-9_-]+$/.test(parts[j]) && /[0-9]/.test(parts[j]))
			|| /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/.test(parts[j])
			? ':id' : parts[j]);
	}
	path = path || '/';
	if (/['"\\]/.test(host + path)) {
		continue;
	}
	key = rows[i].ServiceName + '\n' + host + '\n' + path;
	if (!groups[key]) {
		groups[key] = {service: rows[i].ServiceName, host: host, path: path, count: 0};
		result.push(groups[key]);
	}
	groups[key].count += Number(rows[i].count);
}
result.sort(function (a, b) {
	return b.count - a.count;
});
return JSON.stringify(result.slice(0, 100));

